import json,html
from pathlib import Path
out=Path('output/occurrence-batch-verification')
def read(n):return json.loads((out/n).read_text(encoding='utf8'))
rows=[r for n in ['workflow-results.json','history-results.json','guard-results.json'] for r in read(n)['results']]
assert len(rows)==12 and all(r['status']=='PASS' for r in rows)
assert all(x['unchanged'] for n in ['protected-config.json','reference-checksums.json'] for x in read(n))
cases=''.join('<tr><td>'+html.escape(r['name'])+'</td><td class="pass">PASS</td></tr>' for r in rows)
proofs=[('ทดสอบบันทึก/ย้อนคืน/เลือก/สิทธิ์','workflow-results.json'),('ข้อมูลไม่เลือกและประวัติ Backup/Restore','history-results.json'),('ล็อกสต็อกและ export lease','guard-results.json'),('ผลที่พบก่อนแก้การเลือกค้าง','initial-workflow-results.json'),('หน้าทดสอบ build ล่าสุด ไม่ส่งคำสั่งบันทึก','final-ui-results.json'),('ไฟล์ตั้งค่าที่คงเดิม','protected-config.json'),('แบบ GULF ต้นฉบับ','reference-checksums.json'),('Backup ทดสอบหลังปรับเป็นชุด','Occurrence-batch-QA-backup.zip')]
links=''.join('<li><a href="'+n+'">'+html.escape(t)+'</a></li>' for t,n in proofs)
page='''<!doctype html><html lang="th"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>BOQ/BBS v0.82 — ปรับตำแหน่งและจำนวนเป็นชุด</title><style>*{box-sizing:border-box}body{margin:0;background:#edf2f1;color:#20353e;font:16px/1.65 "Segoe UI",Tahoma,sans-serif}main{max-width:1120px;margin:auto;padding:36px 22px}header,section{padding:24px;background:white;border:1px solid #d7e2df;border-radius:12px;margin-bottom:20px}header{background:#193b45;color:white}h1{font-size:30px;line-height:1.3}h2{font-size:22px}.badge{display:inline-block;padding:5px 14px;border-radius:20px;background:#f2c969;color:#24313b;font-weight:600}.stats{display:grid;grid-template-columns:repeat(4,1fr);gap:12px}.stat{padding:18px;border:1px solid #d7e2df;background:#f3f8f7;border-radius:9px}.stat strong{display:block;font-size:25px}.wrap{overflow:auto}table{border-collapse:collapse;width:100%;min-width:540px}th,td{padding:12px;border-bottom:1px solid #e0e8e6;text-align:left;vertical-align:top}th{background:#f3f8f7}.pass{color:#216746;font-weight:600}a{color:#006f89;overflow-wrap:anywhere}img{max-width:100%;height:auto;border:1px solid #dae3e1;border-radius:6px}figure{margin:20px 0}.mobile{max-width:390px}figcaption{color:#586b73;padding-top:8px}.notice{background:#fff9e9;padding:12px 16px;border-left:4px solid #d2a14d}li{margin:6px 0}footer{color:#5e727a;font-size:14px}@media(max-width:640px){main{padding:16px 12px}header,section{padding:18px}.stats{grid-template-columns:repeat(2,1fr)}h1{font-size:25px}.stat{padding:12px}.stat strong{font-size:23px}}</style></head><body><main>
<header><span class="badge">พัฒนาและทดสอบในเครื่อง · วิศวกรรมยังรอตรวจรับ</span><h1>ปรับตำแหน่งและจำนวนเป็นชุด</h1><p>BOQ/BBS v0.82 · 14 ตุลาคม 2026</p><p>เลือกจากทะเบียนได้ข้ามหน้า ปรับเฉพาะรายการที่เลือก ดูปริมาณก่อน–หลัง และทำต่อหรือย้อนคืนได้เมื่อขัดจังหวะ</p></header>
<section><h2>สิ่งที่เพิ่ม</h2><ul><li>เลือกทีละตำแหน่ง เลือกหน้า หรือเลือกทั้งหมดที่ค้นพบทุกหน้า ตัวกรองและรุ่นโครงการผูกกับชุดเลือกทันที เปลี่ยนตัวกรองแล้วไม่ค้างการเลือกเดิม</li><li>ปรับเฉพาะช่อง Zone/ชั้น/Grid/จำนวนที่เลือก ข้อความว่างในช่องที่เลือกหมายถึงไม่ระบุ จำนวนต้องเป็นจำนวนเต็ม 1–100,000 แสดงสมาชิก ตำแหน่ง จำนวน คอนกรีต แบบหล่อ และเหล็กที่กรอกก่อน–หลัง</li><li>ล็อกโครงการและเก็บข้อมูลก่อน–หลัง ใช้ชุดละไม่เกิน 25 สมาชิก/4MiB ทำต่อหลัง reload หรือย้อนคืนข้อมูลเดิมได้ เผยแพร่ version ใหม่เมื่อครบ</li><li>คง occurrence IDs มิติ จำนวนต่อ Mark และ Frozen เดิม สมาชิกที่เปลี่ยนกลับ Draft เพื่อทบทวนตำแหน่งเหล็กและคำยืนยันไม่มีเหล็กตามขอบเขต</li><li>เพิ่มแถบความคืบหน้าและประวัติที่แยกจากการย้ายชื่อทั้งโครงการ Backup เก็บ manifest และ Restore เป็นประวัติ ไม่เปิดงานหรือการอนุมัติเดิม</li></ul></section>
<section><h2>ผลตรวจปริมาณตัวอย่าง</h2><div class="stats"><div class="stat"><strong>57</strong>สมาชิกที่ปรับทั้งชุด</div><div class="stat"><strong>172 → 114</strong>องค์ประกอบในแถวที่เลือก</div><div class="stat"><strong>176 → 116 ม³</strong>คอนกรีตในแถวที่เลือก</div><div class="stat"><strong>232 ม³</strong>คอนกรีตทั้งโครงการหลังปรับ</div></div><p>ข้อมูลสังเคราะห์สำหรับทดสอบ สมาชิกแรกมีคอนกรีตต่อหน่วย 2 ม³ สมาชิกอื่น 1 ม³ การปรับจำนวนจึงคูณปริมาณต่อหน่วยครั้งเดียว รวมทั้งโครงการ 228 องค์ประกอบ การปรับ Grid ของอีก 3 สมาชิกคงจำนวนและยอดเดิม</p></section>
<section><h2>ตัวอย่างหน้าปรับชุด</h2><figure><img src="batch-preview-desktop.png" alt="ตัวอย่าง57สมาชิก ปรับจำนวน172เป็น114 และคอนกรีต176เป็น116 พร้อมรายการก่อนหลัง"><figcaption>ตัวอย่างก่อนยืนยันบันทึก ระบุชัดว่าปรับชั้นและจำนวนเท่านั้น</figcaption></figure><figure class="mobile"><img src="batch-preview-mobile.png" alt="หน้าตัวอย่างปรับตำแหน่งและจำนวนบนมือถือ"><figcaption>หน้ามือถือไม่มีการล้นแนวนอน</figcaption></figure><figure><img src="final-compiled-preview.png" alt="ทดสอบเปิดหน้าตัวอย่างของ build ล่าสุดโดยไม่บันทึก"><figcaption>เปิดตัวอย่าง 1 รายการจาก build ล่าสุด ตรวจแล้วปิดโดยไม่ส่งคำสั่งบันทึก</figcaption></figure></section>
<section><h2>การตรวจจริง</h2><p>ทดสอบหน่วย 1,424 กรณี / 100 ไฟล์ ผ่าน TypeScript และ Vite build รุ่นสุดท้าย รวม 12 เส้นทางกับ Firebase จำลองจริงภายใต้ Rules เดิม และทดสอบหน้าตัวอย่าง build ล่าสุดแยกต่างหาก</p><div class="wrap"><table><thead><tr><th>เส้นทางที่ตรวจ</th><th>ผล</th></tr></thead><tbody>__CASES__</tbody></table></div><p>ชุดแรกพบการเลือกค้างช่วงเปลี่ยนค้นหา จึงแก้การผูกชุดเลือกกับตัวกรองและ version แล้วทดสอบซ้ำผ่าน ผลไม่ผ่านยังเก็บไว้ คำสั่งใช้ข้อมูลโครงการจำลองที่กู้มาและ Auth seed เก่า ไม่เป็นการยืนยัน Production หรือ Auth ล่าสุด</p></section>
<section><h2>ขอบเขตที่ยังต้องตรวจรับ</h2><p class="notice">ความสามารถนี้จัดข้อมูล Working/Draft ยังไม่รับรอง BBS ใช้ก่อสร้าง ทั้ง 12 ข้อกำหนดเดิมยังคงอยู่</p><ul><li>BS/ACI วัสดุ การปิดรูป 33/51 ตำแหน่ง Mark จากแบบ GULF และการตรวจรับเจ้าของงานยังต้องยืนยัน</li><li>Issued/Consumed และการบังคับ validation ฝั่ง API/Rules ต้องตรวจภายใต้นโยบายของผู้ใช้ การตรวจclientไม่แทนนโยบายฝั่งเซิร์ฟเวอร์</li><li>เลือกได้สูงสุด 10,000 ตำแหน่ง โครงการสูงสุด 5,000 สมาชิก manifest 40MiB เป็นขีดจำกัดระบบ ยังไม่ใช่ผลทดสอบ load สูงสุด ทดสอบจริงรอบนี้57สมาชิก</li><li>ไม่เปลี่ยนสูตรปริมาณ/ชุดกฎขั้นต่ำ ไม่สร้าง PDF/XLSX ใหม่ ไม่ตรวจ native printing ในรอบนี้ Auth ล่าสุด/ไฟล์ Storage ของโครงการอื่นยังไม่กู้ครบ</li></ul><p>ไฟล์ที่ป้องกัน 9 รายการ และแบบ GULF ต้นฉบับ 7 ไฟล์ checksum เดิม ไม่แก้หรือ deploy Rules, Auth, .env, Firebase configuration ไม่มี Cloud Functions หรือคำขอ Production</p></section>
<section><h2>หลักฐาน</h2><ul>__LINKS__</ul><p>ข้อมูลบัญชีและไฟล์ context ไม่เผยแพร่ในรายงานนี้</p></section><footer>รายงานรับรองเฉพาะการทำงานและชุดข้อมูลที่ระบุ</footer></main></body></html>'''
